add('water', 'move', 'Tidal Crash', 'A huge wave rears up behind the foe, curls over it with a foam lip, then crashes down and flattens into a splash that rolls out along the ground.', 'new pixel curling wave (kept inside the frame)', {
  tick: (t, S) => { hit(S, t, 1.5, 2.3, 1.2); if (t > 1.5 && t < 2.2) S.T.dy = ph(t, 1.5, 1.7) * 3; },
  f: (g, t) => { const rise = ph(t, .3, 1.1), crash = ph(t, 1.25, 1.65), fd = 1 - ph(t, 2.1, 2.6); if (rise <= 0) return; const cx = TG.x - 12, R = 30, cy = GY - 50, N = 130; { const fl0 = 1 - crash * .92, sp0 = 1 + crash * .55; for (let x = cx + 2; x <= cx + 2 + R + 9; x++) { const dx = x - cx - 2, top = GY - (GY - (cy - Math.sqrt(Math.max(0, (R + 9) ** 2 - dx * dx)))) * Math.min(1, rise), X = cx + (x - cx) * sp0, Y = GY - (GY - top) * fl0; g.save(); g.globalAlpha = fd; px(g, X, Y, sp0 + 1, GY - Y, '#2a5fc8'); px(g, X, Y + 6, sp0 + 1, Math.max(1, GY - Y - 6), dx > R * .55 ? '#3f86e0' : '#2a5fc8'); px(g, X, Y, sp0 + 1, 3, '#cdeeff'); g.restore(); } } for (let pass = 0; pass < 3; pass++) for (let i = 0; i < N * rise; i++) { const s = i / N; let x, y; if (s < .3) { x = cx + 2 + R; y = lerp(GY, cy, s / .3); } else { const th = ((s - .3) / .7) * Math.PI * 1.12; x = cx + 2 + R * Math.cos(th); y = cy - R * Math.sin(th); } const th_ = s < .3 ? 9 : lerp(9, 3, (s - .3) / .7), fl = 1 - crash * .92, sp = 1 + crash * .55, X = cx + (x - cx) * sp, Y = GY - (GY - y) * fl, r = th_ * (pass === 0 ? 1 : pass === 1 ? .72 : .4) * (1 - crash * .3), col = pass === 0 ? '#2a5fc8' : pass === 1 ? '#4fa3f5' : '#cdeeff'; g.save(); g.globalAlpha = fd; if (pass < 2 || s > .72) disc(g, X, Y, r, col); g.restore(); } if (rise > .8 && crash < 1) for (let i = 0; i < 10; i++) { const u = (t * 1.3 + i / 10) % 1; g.save(); g.globalAlpha = fd; px(g, cx - 26 + hash(i) * 10 - u * 6, cy + 14 + u * 30, 1, 4, '#8fd0ff'); g.restore(); } if (crash > 0) { for (let i = 0; i < 16; i++) { const v = ph(t, 1.45 + hash(i) * .1, 2.3), a = -3.14 + hash(i + 4) * 3.14; if (v > 0 && v < 1) px(g, TG.x - 6 + Math.cos(a) * 38 * v, GY - 8 + Math.sin(a) * 30 * v + 20 * v * v, 3, 3, '#cdeeff'); } ell(g, TG.x - 4, GY - 1, 8 + 36 * ph(t, 1.5, 2.4), 3 + 6 * ph(t, 1.5, 2.4), '#cdeeff', 1); } } });

