add('water', 'move', 'Aqua Jet', 'The user is sealed in a streamlined water shell wrapped by spinning ribbons and rockets across the arena: a long foam wake streams behind, sonic rings pop off the nose, and it detonates on the foe in a splash crown with a shock ring and flying spray.', 'new pixel water torpedo + splash crown', {
  tick: (t, S) => { const u = ph(t, .55, .85), back = ph(t, 1.9, 2.4); S.A.dx = (TG.x - 90) * ease(u) * (1 - ease(back)); hit(S, t, .95, 1.8, 2.0); if (t > .95 && t < 1.4) S.T.dx += ph(t, .95, 1.4) * 5; },
  f: (g, t, S) => {
    const ax = 50 + S.A.dx, mov = t > .5 && t < 1.0, k = Math.min(ph(t, .25, .55), 1 - ph(t, 2.0, 2.4)), L = 40, R = 26 * k, cy = 78;
    if (k > 0) {
      if (t > .5 && t < 1.8) for (let i = 0; i < 16; i++) { const d = 40 + i * 7, w = 3 + (16 - i) * .55; g.save(); g.globalAlpha = .85 * (1 - i / 16) * (1 - ph(t, 1.3, 1.8)); px(g, ax - d, cy - w + Math.sin(i * 1.7 + t * 30) * 2, 6, w * 2, i % 2 ? '#bfe7ff' : '#e8fbff'); g.restore(); }
      if (mov) for (let i = 0; i < 8; i++) line(g, ax - 44, 58 + i * 5, ax - 44 - 24 - hash(i) * 30, 58 + i * 5, '#cdeeff', 1);
      g.save(); g.globalAlpha = .4 * k; g.fillStyle = '#4fa3f5'; g.beginPath(); g.moveTo(ax + L, cy); g.bezierCurveTo(ax + L * .4, cy - R * 1.25, ax - L * .7, cy - R * 1.1, ax - L, cy); g.bezierCurveTo(ax - L * .7, cy + R * 1.1, ax + L * .4, cy + R * 1.25, ax + L, cy); g.fill(); g.globalAlpha = k; g.strokeStyle = '#cdeeff'; g.lineWidth = 1.5; g.stroke(); g.globalAlpha = .5 * k; g.strokeStyle = '#fff'; g.lineWidth = 1; g.beginPath(); g.moveTo(ax + L * .7, cy - R * .5); g.quadraticCurveTo(ax, cy - R * 1.0, ax - L * .6, cy - R * .6); g.stroke(); g.restore();
      for (let r = 0; r < 3; r++) for (let x = ax - L + 5; x < ax + L - 3; x += 2) { const u = (x - (ax - L)) / (2 * L), env = Math.pow(Math.sin(u * Math.PI), .8) * R * .9; px(g, x, cy + Math.sin(u * 9 - t * 28 + r * 2.1) * env, 2, 2, r % 2 ? '#fff' : '#8fd0ff'); }
      if (mov) for (let i = 0; i < 3; i++) { const e = (t * 6 + i * .33) % 1; g.save(); g.globalAlpha = 1 - e; ell(g, ax + L + 4 + e * 24, cy, 3 + e * 8, 6 + e * 24, '#e8fbff', 1, -1.2, 1.2); g.restore(); }
    }
    if (t > .95) { const e = ph(t, .95, 1.8), fd = 1 - ph(t, 1.5, 1.9), x0 = TG.x - 6; flash(g, t, .95, 1.08, '#e8fbff', .4); for (let s = 0; s < 14; s++) { const a = -3.14 + s * .24, len = (12 + hash(s) * 20) * Math.min(1, e * 1.6); g.save(); g.globalAlpha = fd; line(g, x0 + Math.cos(a) * 6, GY - 3, x0 + Math.cos(a) * (6 + len * 1.4), GY - 3 + Math.sin(a) * len * 1.6, '#4fa3f5', 3); line(g, x0 + Math.cos(a) * 6, GY - 3, x0 + Math.cos(a) * (6 + len * 1.4), GY - 3 + Math.sin(a) * len * 1.6, '#cdeeff', 1); g.restore(); } for (let i = 0; i < 16; i++) { const v = ph(t, 1.0 + hash(i) * .08, 1.9), a = -3.1 + hash(i + 3) * 3.1; if (v > 0 && v < 1) px(g, x0 + Math.cos(a) * 38 * v, TG.y + Math.sin(a) * 32 * v + 20 * v * v, 3, 3, '#cdeeff'); } ell(g, x0, GY - 1, 8 + 50 * e, 3 + 8 * e, '#cdeeff', 2); ell(g, x0, GY - 1, 5 + 32 * e, 2 + 5 * e, '#4fa3f5', 1); if (e < .4) star(g, x0, TG.y, 34 * (1 - e * 2.2) + 6, '#fff', 12, 0); } } });
add('water', 'move', 'Water Shuriken', 'Five spinning four-point water stars are thrown in a fan; each leaves droplets behind and pops into a splash on the foe.', 'new pixel water stars', {
  tick: (t, S) => { hit(S, t, 1.0, 2.0, 1.2); },
  f: (g, t) => { for (let i = 0; i < 5; i++) { const a = .4 + i * .12, u = ph(t, a, a + .7); if (u <= 0) continue; const to = { x: TG.x - 8, y: TG.y - 20 + i * 10 }, from = { x: 84, y: 72 }, off = (i - 2) * 12; if (u < 1) { const p = arcP(from, to, off * .6, u); for (let k = 1; k < 6; k++) { const q = arcP(from, to, off * .6, Math.max(0, u - k * .04)); px(g, q.x, q.y, 2, 2, k % 2 ? '#8fd0ff' : '#cdeeff'); } wstar(g, p.x, p.y, 7, t * 20 + i, '#4fa3f5', '#e8fbff'); } else { const e = ph(t, a + .7, a + 1.0); if (e < 1) star(g, to.x, to.y, 10 * e + 3, '#cdeeff', 6, i); } } } });

