add('ice', 'move', 'Hailstorm', 'No hit: the sky turns dark and hail pours across the arena, bouncing off the ground; everything gets pelted and ice moves get a boost.', 'new pixel hailstones + cloud', {
  tick: (t, S) => { hit(S, t, 1.0, 2.4, .7); },
  b: (g, t) => { const k = env(t, .2, .8, 2.2, 2.6); g.save(); g.globalAlpha = .4 * k; g.fillStyle = '#0a1a3a'; g.fillRect(-5000, -5000, 10000, 10000); g.restore(); },
  f: (g, t) => { const k = env(t, .2, .8, 2.2, 2.6); for (let i = 0; i < 6; i++) { const x = 10 + i * 42; g.save(); g.globalAlpha = k; disc(g, x, 10, 15, '#566488'); disc(g, x + 9, 13, 11, '#6a7aa0'); disc(g, x - 10, 14, 10, '#44527a'); g.restore(); } if (t > .6 && t < 2.4) for (let i = 0; i < 24; i++) { const u = (t * 1.5 + hash(i)) % 1, x = hash(i + 4) * LW - u * 26, y = 24 + u * (GY - 24); if (y < GY - 3) { disc(g, x, y, 2, '#fff'); px(g, x + 3, y - 6, 1, 6, '#cdeeff'); } else if (u > .93) { px(g, x - 3, GY - 6, 1, 3, '#fff'); px(g, x + 3, GY - 6, 1, 3, '#fff'); px(g, x, GY - 8, 1, 3, '#fff'); } } } });

