add('fighting', 'move', 'Dynamic Punch', 'One huge flaming fist: the user dashes in and lands a single heavy hit with a shock ring, and the foe is left dizzy with stars circling its head.', 'existing "fist", "impact", "shine" sprites + new pixel shock ring', {
  tick: (t, S) => { const u = ph(t, .4, .75), back = ph(t, 2.2, 2.6); S.A.dx = (TG.x - 94) * ease(u) * (1 - ease(back)); if (t > 1.0 && t < 2.2) { S.T.hurt = true; S.T.dx = t < 1.3 ? -2 : Math.sin(t * 40); } },
  f: (g, t, S) => { const ax = 50 + S.A.dx; if (t > .7 && t < 1.1) { spr(g, 'fist', ax + 34, 76, 46, 0, 1, 1); tinted(g, 'fist', ax + 34, 76, 46, '#ff5a2a', .4, 1); halo(g, ax + 34, 76, 22, '#ff8a2a'); } if (t > .95 && t < 2.2) { const e = ph(t, .95, 1.5); ell(g, TG.x - 12, TG.y, 6 + 40 * e, 6 + 40 * e, '#fff', 2); ell(g, TG.x - 12, TG.y, 4 + 30 * e, 4 + 30 * e, '#ff8a2a', 2); spr(g, 'impact', TG.x - 12, TG.y, 50 * (1 - e * .4), 0, 1 - e * .5); } if (t > 1.3 && t < 2.2) for (let i = 0; i < 3; i++) { const a = t * 7 + i * 2.1; spr(g, 'shine', TG.x - 6 + Math.cos(a) * 14, TG.y - 38 + Math.sin(a) * 4, 8, t * 3, 1); } } });
add('fighting', 'move', 'Bulk Up', 'No hit: the user flexes and a red aura flares with rising flames and up-arrows; attack is boosted for the rest of the fight.', 'new pixel aura + arrows', {
  tick: (t, S) => { S.A.tint = ['#ff3a2a', .22 * Math.sin(t * 6) ** 2]; },
  f: (g, t) => { const k = ph(t, .2, .6) * (1 - ph(t, 2.2, 2.6)); for (let i = 0; i < 34; i++) { const u = (t * 1.3 + hash(i)) % 1, x = 50 + (hash(i + 2) - .5) * 44, y = 106 - u * 72; g.save(); g.globalAlpha = k; px(g, x, y, 2, 4, u < .5 ? '#ff3a2a' : '#ffb84d'); g.restore(); } for (let i = 0; i < 3; i++) { const u = (t * .9 + i / 3) % 1, y = 56 - u * 26; g.save(); g.globalAlpha = k * (1 - u); arrowUp(g, 30 + i * 20, y, '#ff5a3a'); g.restore(); } g.save(); g.globalAlpha = k; ell(g, 50, 80, 30 + 3 * Math.sin(t * 8), 36, '#ff5a3a', 1); g.restore(); } });

// ----- POISON
add('poison', 'move', 'Poison Jab', 'The user lunges and thrusts a long glowing purple spike straight through the foe; venom drips off the tip.', 'new pixel spike + existing "poisonwisp" sprite', {
  tick: (t, S) => { const u = ph(t, .5, .8), back = ph(t, 1.9, 2.4); S.A.dx = (TG.x - 110) * ease(u) * (1 - ease(back)); hit(S, t, .85, 1.9, 1.6); if (t > .85) S.T.tint = ['#a040c0', .3]; },
  f: (g, t, S) => { const ax = 50 + S.A.dx; if (t > .55 && t < 1.8) { const ext = ph(t, .65, .85) * (1 - ph(t, 1.5, 1.8)), x0 = ax + 22, len = 46 * ext; for (let i = 0; i < len; i += 2) { const w = Math.max(1, 4 - i * .09); px(g, x0 + i, 76 - w, 2, w * 2, '#6a1a98'); px(g, x0 + i, 76 - w * .5, 2, w, '#e0b0ff'); } spr(g, 'poisonwisp', x0 + len, 76, 16, 0, .9); halo(g, x0 + len, 76, 10, '#c070ff'); for (let i = 0; i < 4; i++) px(g, x0 + len - 8 - i * 4, 82 + ((t * 20 + i * 3) % 8), 2, 3, '#a040c0'); } if (t > .85 && t < 1.5) star(g, TG.x - 22, 76, 14 * (1 - ph(t, .85, 1.5)) + 4, '#e0b0ff', 8, 0); } });
add('poison', 'move', 'Smog Cloud', 'A thick purple-grey smog rolls out in a widening cone, reaches the foe and makes it cough and sway.', 'new pixel smog', {
  tick: (t, S) => { if (t > 1.2 && t < 2.4) { S.T.dx = Math.sin(t * 10) * 1.6; S.T.tint = ['#7a4a98', .3]; } },
  f: (g, t) => { const k = 1 - ph(t, 2.2, 2.6); for (let i = 0; i < 24; i++) { const u = ph(t, .4 + hash(i) * .3, 1.4); if (u <= 0) continue; const x = lerp(84, TG.x - 6, u) + Math.sin(i * 2 + t * 3) * 6, y = lerp(76, TG.y, u) + Math.cos(i * 3 + t * 2) * (6 + u * 14), r = 5 + u * 9 + hash(i + 3) * 3; g.save(); g.globalAlpha = .65 * k; disc(g, x, y, r, i % 2 ? '#6a4a84' : '#8a64a8'); disc(g, x - 2, y - 2, r * .55, '#a888c8'); g.restore(); } if (t > 1.3 && t < 2.4) for (let i = 0; i < 3; i++) { const x = TG.x - 12 + i * 8, y = TG.y - 38 - ((t * 30 + i * 10) % 20); px(g, x, y, 3, 3, '#e8e0f0'); px(g, x + 1, y + 3, 1, 1, '#2a1a38'); } } });

// ----- GROUND
add('ground', 'move', 'Sand Attack', 'The user kicks up a spray of sand that arcs into the foe\'s face; a dust cloud swirls round its head and a crossed-out target shows its aim dropping.', 'new pixel sand', {
  tick: (t, S) => { if (t > 1.2 && t < 2.3) { S.T.tint = ['#c8a050', .4]; S.T.dx = Math.sin(t * 20) * 1.2; } },
  f: (g, t) => { for (let i = 0; i < 34; i++) { const u = ph(t, .4 + hash(i) * .2, 1.3), p = arcP({ x: 70, y: 96 }, { x: TG.x - 8 + (hash(i + 3) - .5) * 20, y: TG.y - 18 + (hash(i + 5) - .5) * 20 }, 20 + hash(i + 2) * 20, u); if (u > 0 && u < 1) px(g, p.x, p.y, 2, 2, hash(i + 8) > .5 ? '#f2d890' : '#c8a858'); } if (t > 1.2 && t < 2.4) { const k = env(t, 1.2, 1.5, 2.0, 2.4); for (let i = 0; i < 9; i++) { const a = t * 4 + i; puff(g, TG.x - 6 + Math.cos(a) * 20, TG.y - 16 + Math.sin(a * 1.3) * 14, 7, '#d8b868', .55 * k); } g.save(); g.globalAlpha = k; ell(g, TG.x - 6, TG.y - 46, 8, 8, '#ff5a3a', 1); line(g, TG.x - 12, TG.y - 52, TG.x, TG.y - 40, '#ff5a3a', 1); g.restore(); } } });
add('ground', 'move', 'Drill Run', 'The user digs in and drills along underground toward the foe, a moving mound and spiral dust marking its path, then erupts right under it in a spray of dirt.', 'new pixel mound + existing "rock" sprites', {
  tick: (t, S) => { S.A.a = t > .5 && t < 1.4 ? 0 : 1; if (t > 1.3 && t < 2.1) { S.T.dy = -Math.sin(ph(t, 1.3, 2.1) * Math.PI) * 20; S.T.hurt = true; } },
  b: (g, t) => { if (t > .4 && t < 2.5) { const u = ph(t, .5, 1.3), x = lerp(50, TG.x - 6, ease(u)); for (let i = 0; i < 8; i++) { const xx = x - i * 7; if (xx < 50) continue; disc(g, xx, GY - 3, 6 - i * .4, '#7a5a2a'); disc(g, xx, GY - 5, 4 - i * .3, '#a88848'); } for (let i = 0; i < 10; i++) px(g, x - 16 + hash(i) * 30, GY - 8 - ((t * 50 + i * 7) % 14), 2, 2, '#c8a858'); if (u < 1) for (let k = 0; k < 8; k++) { const a = t * 20 + k; px(g, x + Math.cos(a) * 5, GY - 6 + Math.sin(a) * 3, 2, 2, '#fff'); } } },
  f: (g, t) => { if (t > 1.25 && t < 2.3) { const u = ph(t, 1.25, 1.5), fd = 1 - ph(t, 1.9, 2.3), hh = 46 * u * fd + 4; for (let y = 0; y < hh; y += 2) { const w = 11 - y * .1 + hash(y + sn(t, 16)) * 2; px(g, TG.x - w, GY - 2 - y, w * 2, 2, '#6a4a22'); px(g, TG.x - w * .6, GY - 2 - y, w * 1.2, 2, '#9a7a42'); } for (let i = 0; i < 8; i++) { const v = ph(t, 1.25 + hash(i) * .2, 2.3); if (v > 0 && v < 1) spr(g, 'rock' + (1 + i % 3), TG.x + (hash(i + 3) - .5) * 60 * v, GY - 10 - Math.sin(v * Math.PI) * (36 + hash(i) * 30), 12, v * 9, 1); } } } });

// ----- FLYING
add('flying', 'move', 'Roost', 'No hit: the user settles, a soft glow wraps it, feathers drift down and green plus-signs float up as HP is restored.', 'existing "feather" sprite + new pixel glow', {
  tick: (t, S) => { S.A.tint = ['#bfffd0', .25 * Math.sin(t * 3) ** 2]; },
  f: (g, t) => { const k = ph(t, .2, .7) * (1 - ph(t, 2.2, 2.6)); halo(g, 50, 80, 34, '#bfffd0', k * .8); for (let i = 0; i < 8; i++) { const u = (t * .7 + i / 8) % 1, a = i * .79 + t; spr(g, 'feather', 50 + Math.cos(a) * 24, 50 + u * 50, 13, Math.sin(u * 9 + i) * .9, k * (1 - Math.abs(u - .5) * 1.2)); } for (let i = 0; i < 6; i++) { const u = (t * .9 + i / 6) % 1, x = 34 + i * 7, y = 100 - u * 60; g.save(); g.globalAlpha = k * (1 - u); px(g, x, y - 3, 1, 7, '#7dff9a'); px(g, x - 3, y, 7, 1, '#7dff9a'); g.restore(); } } });
add('flying', 'move', 'Aerial Ace', 'The user becomes a blur and zig-zags through the foe in a Z path; every pass leaves a white slash and the afterimages cannot be tracked.', 'new pixel slashes + afterimages', {
  tick: (t, S) => { const W = [[60, 62], [176, 46], [196, 96], [150, 58], [204, 92]], k = ph(t, .5, 1.6) * 4, i = Math.min(3, Math.floor(k)), f = k - i, hx = lerp(W[i][0], W[i + 1][0], f), hy = lerp(W[i][1], W[i + 1][1], f); if (t > .5 && t < 1.6) { S.A.dx = hx - 50; S.A.dy = hy - 80; } hit(S, t, .8, 1.9, 1.4); },
  b: (g, t, S) => { const W = [[60, 62], [176, 46], [196, 96], [150, 58], [204, 92]]; if (t > .5 && t < 1.7) for (let n = 1; n < 5; n++) { const k = Math.max(0, ph(t - n * .06, .5, 1.6)) * 4, i = Math.min(3, Math.floor(k)), f = k - i; drawActor(g, S, 'A', lerp(W[i][0], W[i + 1][0], f), .5 - n * .1, lerp(W[i][1], W[i + 1][1], f) - 80); } },
  f: (g, t) => { const W = [[60, 62], [176, 46], [196, 96], [150, 58], [204, 92]], fd = 1 - ph(t, 1.6, 2.1); for (let i = 0; i < 4; i++) { const e = ph(t, .5 + i * .275, .5 + i * .275 + .22); if (e <= 0) continue; const x1 = lerp(W[i][0], W[i + 1][0], e), y1 = lerp(W[i][1], W[i + 1][1], e); g.save(); g.globalAlpha = fd; line(g, W[i][0], W[i][1], x1, y1, '#4a6a9a', 4); line(g, W[i][0], W[i][1], x1, y1, '#cde4ff', 2); line(g, W[i][0], W[i][1], x1, y1, '#fff', 1); g.restore(); if (e < 1) spr(g, 'shine', x1, y1, 12, t * 5, 1); else star(g, W[i + 1][0], W[i + 1][1], 9 * fd, '#fff', 6, i); } } });

// ----- PSYCHIC
add('psychic', 'move', 'Reflect', 'No hit: a shimmering hex-tile barrier unfolds in front of the user; a shot from the foe hits it, ripples and is thrown back.', 'new pixel barrier + existing "mistball" sprite', {
  tick: (t, S) => { if (t > 1.6 && t < 2.2) S.T.hurt = true; },
  f: (g, t) => { const k = ph(t, .2, .6) * (1 - ph(t, 2.3, 2.6)), imp = ph(t, 1.2, 1.4); if (k <= 0) return; for (let r = -3; r <= 3; r++) for (let c = -1; c <= 1; c++) { const x = 84 + c * 10 + (r % 2 ? 5 : 0), y = 76 + r * 11, on = (Math.sin(t * 4 + r + c) + 1) / 2, near = Math.max(0, 1 - Math.hypot(x - 84, y - 76) / 30) * (imp > 0 && imp < 1 ? 1 : 0); g.save(); g.globalAlpha = k * (.3 + .4 * on + .5 * near); hexo(g, x, y, 6, near > .2 ? '#ffffff' : '#7ad0ff'); g.restore(); } const u = ph(t, .9, 1.25), v = ph(t, 1.4, 1.9); if (u > 0 && u < 1) { const x = lerp(TG.x - 10, 90, u); spr(g, 'mistball', x, 76, 14, 0, 1); halo(g, x, 76, 8, '#ff7ac0'); } else if (v > 0 && v < 1) { const x = lerp(90, TG.x - 10, v); spr(g, 'mistball', x, 76 - Math.sin(v * Math.PI) * 6, 14, 0, 1); halo(g, x, 76, 8, '#ff7ac0'); } if (imp > 0 && imp < 1) star(g, 92, 76, 14 * imp, '#fff', 8, 0); } });
add('psychic', 'move', 'Dream Eater', 'The foe is put to sleep with "zzz" floating above it; a pink-violet mist is drawn out of it, curls across the arena and heals the user.', 'new pixel mist + sleep marks', {
  tick: (t, S) => { if (t > .3) S.T.tint = ['#4a2a78', .4]; S.A.tint = ['#7dff9a', .2 * ph(t, 1.0, 1.6)]; },
  f: (g, t) => { for (let i = 0; i < 3; i++) { const y = TG.y - 40 - i * 8 - ((t * 10) % 8), x = TG.x - 4 + i * 8; g.save(); g.globalAlpha = ph(t, .3, .6); zz(g, x, y, 5 - i, '#e8e0ff'); g.restore(); } if (t > .9) { const fd = 1 - ph(t, 2.2, 2.6); for (let i = 0; i < 28; i++) { const u = (t * .7 + i / 28) % 1, p = arcP({ x: TG.x - 8, y: TG.y - 8 }, { x: 62, y: 74 }, -30, u); g.save(); g.globalAlpha = fd * (.5 + .5 * Math.sin(u * 3.14)); disc(g, p.x + Math.sin(u * 20 + i) * 3, p.y, 3 - u * 1.4, i % 2 ? '#d070ff' : '#ff90e0'); g.restore(); } for (let i = 0; i < 4; i++) { const u = (t * .8 + i / 4) % 1; g.save(); g.globalAlpha = (1 - u) * fd * ph(t, 1.4, 1.8); px(g, 40 + i * 6, 70 - u * 20 - 1, 1, 3, '#7dff9a'); px(g, 39 + i * 6, 70 - u * 20, 3, 1, '#7dff9a'); g.restore(); } } } });

