// ===== TWO MORE MOVES FOR EVERY TYPE - shared helpers
const rushTick = (t0, t1, b0, b1, h0, h1, amp = 1.8) => (t, S) => { const u = ph(t, t0, t1), back = ph(t, b0, b1); S.A.dx = (TG.x - 40 - 46) * ease(u) * (1 - ease(back)); hit(S, t, h0, h1, amp); };
const shock = (g, x, y, e, c1, c2, r = 30) => { if (e <= 0 || e >= 1) return; ell(g, x, y, 6 + r * e, 3 + r * .5 * e, c1, 2); ell(g, x, y, 3 + r * .6 * e, 2 + r * .3 * e, c2, 1); };

