const ORIG_N = FX.length;

// ================= move variations mockup: helpers =================
let FXc = TG.x - 6, FYc = TG.y;
const soft = (g, x, y, r, rgb, a = 1) => { const q = g.createRadialGradient(x, y, 0, x, y, r); q.addColorStop(0, `rgba(${rgb},${.6 * a})`); q.addColorStop(.55, `rgba(${rgb},${.28 * a})`); q.addColorStop(1, `rgba(${rgb},0)`); g.fillStyle = q; g.fillRect(x - r, y - r, r * 2, r * 2); };
function serpPts(x0, head, t, o) { const P = []; for (let x = Math.round(x0); x <= head; x++) { const k = (x - x0) / Math.max(10, head - x0), kk = .45 + .55 * k, h = Math.max(0, Math.sin(x / o.wl * 6.283 - t * o.sp + (o.ph || 0))) * o.amp * kk, r = o.th * kk; P.push({ x, h, r, y: GY - 1 - h + r * .6 }); } return P; }
function serp(g, x0, head, t, o) { g.save(); g.beginPath(); g.rect(0, 0, LW, GY); g.clip(); const P = serpPts(x0, head, t, o).filter(p => p.h > .8); for (const p of P) disc(g, p.x, p.y, p.r + 1, o.c1); for (const p of P) disc(g, p.x, p.y, p.r, o.c2); for (const p of P) disc(g, p.x, p.y - p.r * .3, p.r * .45, o.c3); if (o.tg) P.forEach((p, i) => { if (i % o.tg === 0 && p.h > 3) { line(g, p.x, p.y - p.r + 1, p.x + 2, p.y - p.r - 5, o.c1, 2); px(g, p.x + 2, p.y - p.r - 6, 1, 1, o.c3); } }); g.restore(); }
function arch(g, x0, x1, h, k, c1, c2, c3, th, tg, t) { const n = 50, pts = []; for (let i = 0; i <= n * k; i++) { const u = i / n; pts.push({ x: lerp(x0, x1, u) + Math.sin(u * 9 + t * 4) * 2, y: GY - 1 - Math.sin(u * Math.PI) * h, r: th * (.45 + .55 * Math.sin(u * Math.PI)) + .6, u }); } for (const p of pts) disc(g, p.x, p.y, p.r + 1, c1); for (const p of pts) disc(g, p.x, p.y, p.r, c2); for (const p of pts) disc(g, p.x, p.y - p.r * .3, p.r * .4, c3); if (tg) pts.forEach((p, i) => { if (i % tg === 0 && i > 2) { const sx = p.u < .5 ? -1 : 1; line(g, p.x, p.y - p.r, p.x + sx * 2, p.y - p.r - 5, c1, 2); px(g, p.x + sx * 2, p.y - p.r - 6, 1, 1, c3); } }); }
function bez(g, p0, p1, p2, k, th, c1, c2, c3, tg) { const n = 40, pts = []; for (let i = 0; i <= n * k; i++) { const u = i / n, v = 1 - u, x = v * v * p0.x + 2 * v * u * p1.x + u * u * p2.x, y = v * v * p0.y + 2 * v * u * p1.y + u * u * p2.y, dx = 2 * v * (p1.x - p0.x) + 2 * u * (p2.x - p1.x), dy = 2 * v * (p1.y - p0.y) + 2 * u * (p2.y - p1.y), L = Math.hypot(dx, dy) || 1; pts.push({ x, y, nx: -dy / L, ny: dx / L, r: th * (1 - .55 * u) + .5 }); } for (const p of pts) disc(g, p.x, p.y, p.r + 1, c1); for (const p of pts) disc(g, p.x, p.y, p.r, c2); for (const p of pts) disc(g, p.x, p.y, p.r * .4, c3); if (tg) pts.forEach((p, i) => { if (i % tg === 0 && i > 3) { const s = i % (tg * 2) ? 1 : -1; line(g, p.x + p.nx * p.r * s, p.y + p.ny * p.r * s, p.x + p.nx * (p.r + 4) * s, p.y + p.ny * (p.r + 4) * s, c1, 2); } }); return pts[pts.length - 1]; }
const fireRock = (g, x, y, w, rot, a = 1) => { halo(g, x, y, w * .9, '#ff6a1a', .75 * a); tinted(g, 'rock' + (1 + Math.floor(Math.abs(rot)) % 3), x, y, w, '#ff3a10', .6, 0, rot); spr(g, 'fireball', x + w * .12, y - w * .25, w * .8, 0, .9 * a); };
const ring = (g, x, y, e, c1, c2, r = 24, fl = 1) => { g.save(); g.globalAlpha = (1 - e) * fl; ell(g, x, y, 4 + r * e, 4 + r * e, c1, 2); ell(g, x, y, 2 + r * .66 * e, 2 + r * .66 * e, c2, 1); g.restore(); };
function ghostSp(g, x, y, s, a = 1) { g.save(); g.globalAlpha = a; disc(g, x, y, 4 * s, '#fff'); px(g, x - 4 * s, y, 8 * s, 4 * s, '#fff'); for (let i = 0; i < 4; i++) px(g, x - 4 * s + i * 2 * s, y + 4 * s, 2 * s, (i % 2 ? 2 : 3) * s, '#fff'); px(g, x - 2.5 * s, y - 1 * s, 1.6 * s, 2.4 * s, '#2a2040'); px(g, x + 1 * s, y - 1 * s, 1.6 * s, 2.4 * s, '#2a2040'); px(g, x - 1 * s, y + 2.2 * s, 2 * s, 1 * s, '#2a2040'); g.restore(); }
function gear(g, x, y, r, rot, c1, c2) { for (let i = 0; i < 8; i++) { const a = rot + i * .785; line(g, x + Math.cos(a) * r * .7, y + Math.sin(a) * r * .7, x + Math.cos(a) * (r + 3), y + Math.sin(a) * (r + 3), c1, 3); } disc(g, x, y, r, c1); disc(g, x, y, r - 1.5, c2); disc(g, x, y, r * .35, c1); }
function bug(g, x, y, c, w) { px(g, x, y, 3, 3, c); px(g, x - 1, y - 1 + (w ? 1 : 0), 1, 1, '#e8f0ff'); px(g, x + 2, y - 1 + (w ? 0 : 1), 1, 1, '#e8f0ff'); }

