function coil(g, t, front) { const k = ph(t, .35, 1.5) * (1 - ph(t, 2.0, 2.3)); if (k <= 0) return; const N = 70; for (let i = Math.floor(N * k); i >= 0; i--) { const s = i / N, a = s * 12.5 + t * 2, z = Math.sin(a), r = 36 - s * 10 * 0; if ((z >= 0) !== !!front) continue; const x = FXc + Math.cos(a) * r, y = GY - 6 - s * 82 + z * 3, w = 5.5 - s * 1.5 + (z > 0 ? .8 : 0); disc(g, x, y, w + 1, '#2a1070'); disc(g, x, y, w, z > 0 ? '#6a38f0' : '#4a28b0'); disc(g, x, y + 1, w * .5, '#c8a8ff'); if (i % 9 === 0) { line(g, x, y - w, x, y - w - 4, '#2a1070', 2); } } if (front) { const s = k, a = s * 12.5 + t * 2, x = FXc + Math.cos(a) * 36, y = GY - 6 - s * 82; disc(g, x, y, 8, '#2a1070'); disc(g, x, y, 7, '#7038f8'); px(g, x - 3, y - 2, 2, 2, '#ffe27a'); px(g, x + 2, y - 2, 2, 2, '#ffe27a'); line(g, x - 5, y - 6, x - 8, y - 12, '#c8a8ff', 2); line(g, x + 5, y - 6, x + 8, y - 12, '#c8a8ff', 2); } }
