add('ground', 'move', 'Mud Splat Barrage', 'Heavy mud balls are lobbed in a high arc; each lands with a wet splat that sticks on the foe and the floor in blobby stars, dripping down and slowing it, and the splats slide away slowly.', 'new pixel mud balls + splats', {
  tick: (t, S) => { for (let i = 0; i < 4; i++) hit(S, t, 1.0 + i * .22, 1.15 + i * .22, 1.3); if (t > 1.0) S.T.tint = ['#6a4a22', .3]; },
  f: (g, t) => { for (let i = 0; i < 4; i++) { const a = .4 + i * .22, u = ph(t, a, a + .6), end = { x: FXc - 14 + (i % 2) * 18, y: FYc - 14 + i * 8 }; if (u <= 0) continue; if (u < 1) { const p = arcP({ x: 70, y: 70 }, end, 44, u); disc(g, p.x, p.y, 6, '#3a2810'); disc(g, p.x, p.y, 5, '#6a4a22'); disc(g, p.x - 1, p.y - 2, 2, '#a88848'); } else { const e = ph(t, a + .6, a + 1.1), fd = 1 - ph(t, 1.9, 2.5); g.save(); g.globalAlpha = fd; for (let s = 0; s < 8; s++) { const an = s * .785, r = 8 + 10 * Math.min(1, e * 3) * (s % 2 ? .6 : 1); disc(g, end.x + Math.cos(an) * r * .8, end.y + Math.sin(an) * r * .7, 3, s % 2 ? '#6a4a22' : '#4a3418'); } disc(g, end.x, end.y, 8, '#6a4a22'); for (let d = 0; d < 3; d++) px(g, end.x + (d - 1) * 6, end.y + 6 + e * 10 * (1 + d % 2), 2, 4, '#4a3418'); g.restore(); } } } });
add('ground', 'var', 'Fissure Rift', 'Variation of Earthquake for ground: the earth splits in a jagged glowing crack that races across the ground to the foe and yawns open into a wide dark rift with a lava-lit edge; rocks tumble in, dust and heat rise, the foe stumbles, and it grinds shut.', 'new pixel crack + existing "rock" sprites', {
  tick: (t, S) => { if (t > 1.0 && t < 2.1) { S.T.rot = Math.sin(t * 20) * 3; S.T.dy = 4 * Math.sin(ph(t, 1.0, 2.1) * Math.PI); S.T.hurt = sn(t, 8) % 2 === 0; } },
  b: (g, t) => { const k = ph(t, .35, 1.0), open = easeO(ph(t, .9, 1.35)) * (1 - ease(ph(t, 1.9, 2.4))); let lx = 54, ly = GY; for (let i = 1; i <= 40 * k; i++) { const x = lerp(54, FXc + 30, i / 40), y = GY + Math.sin(i * 1.7) * 1.6 + (i % 4) * .6; line(g, lx, ly, x, y, '#1a1008', 4); line(g, lx, ly - 1, x, y - 1, '#e0602a', 2); line(g, lx, ly - 1, x, y - 1, '#ffd34d', 1); lx = x; ly = y; } if (open > 0) { const cx = FXc, w = 34 * open, d = 14 * open; g.fillStyle = '#0a0604'; g.beginPath(); g.moveTo(cx - w, GY - 2); for (let i = 0; i <= 8; i++) g.lineTo(cx - w + i * w / 4, GY - 2 + (i % 2 ? 2 : 0)); for (let i = 8; i >= 0; i--) g.lineTo(cx - w * .7 + i * w * 1.4 / 8, GY - 2 + d + (i % 2 ? 5 : 0)); g.closePath(); g.fill(); g.fillStyle = '#ff7a22'; g.fillRect(cx - w * .8, GY + d * .5, w * 1.6, 2); g.fillStyle = '#ffd34d'; g.fillRect(cx - w * .5, GY + d * .5 + 1, w, 1); halo(g, cx, GY + 2, 30 * open, '#ff6a1a', .5); } },
  f: (g, t) => { const open = easeO(ph(t, .9, 1.35)) * (1 - ease(ph(t, 1.9, 2.4))); if (open > 0) { for (let i = 0; i < 7; i++) { const v = ph(t, 1.0 + hash(i) * .3, 2.0); if (v > 0 && v < 1) spr(g, 'rock' + (1 + i % 3), FXc + (hash(i + 2) - .5) * 70, GY - 30 + v * 36 + hash(i) * 10, 9, v * 8, 1 - v * .6); } for (let i = 0; i < 6; i++) puff(g, FXc + (hash(i) - .5) * 50, GY - 4 - ((t * 20 + i * 7) % 30), 5, '#c8b078', .4 * open); for (let i = 0; i < 6; i++) { const u = (t * .9 + i / 6) % 1; px(g, FXc + (hash(i + 4) - .5) * 40, GY - u * 36, 2, 2, '#ffb84d'); } } } });


// ================= round 4 part 2 =================
// ===== FLYING
add('flying', 'move', 'Air Cutter Volley', 'Five pale crescent air blades fan out from the user, each with whistling wind streaks, and slice across the foe from different angles, leaving thin white cut marks.', 'new pixel crescents + wind lines', {
  tick: (t, S) => { for (let i = 0; i < 5; i++) hit(S, t, 1.0 + i * .12, 1.15 + i * .12, 1.3); },
  f: (g, t) => { for (let i = 0; i < 5; i++) { const a = .45 + i * .12, u = ph(t, a, a + .55), ang = (i - 2) * .22; if (u <= 0) continue; if (u < 1) { const x = lerp(76, FXc - 6, u), y = lerp(70, FYc - 6 + (i - 2) * 9, u) + Math.sin(u * 5 + i) * 3; for (let k = 1; k < 5; k++) line(g, x - k * 9, y + (hash(k + i) - .5) * 8, x - k * 9 - 8, y + (hash(k + i) - .5) * 8, 'rgba(255,255,255,.6)', 1); crescent(g, x, y, 13, -1.6 + ang, 1.6 + ang, 3.2, '#8a78d0', '#d8d0ff', '#fff'); } else { const e = ph(t, a + .55, a + .9); if (e > 0 && e < 1) { const y = FYc - 6 + (i - 2) * 9; line(g, FXc - 24 + e * 8, y - 8, FXc + 12 - e * 6, y + 8, '#fff', 1); star(g, FXc - 6, y, 8 * (1 - e) + 2, '#fff', 6, i); } } } } });
add('flying', 'move', 'Dive Bomb', 'The user soars up out of sight (its shadow grows on the ground under the foe), then plummets as a streak with wind rings and trailing feathers, crashing into the foe in a big shock ring and feather burst.', 'existing "feather" sprite + new pixel shadow, streak and rings', {
  tick: (t, S) => { const up = ph(t, .4, .9), dn = ph(t, 1.35, 1.55); S.A.a = t > .85 && t < 1.55 ? 0 : 1; S.A.dy = -120 * up * (1 - dn); S.A.dx = (TG.x - 96) * dn; hit(S, t, 1.55, 2.1, 1.8); if (t > 1.55 && t < 2.2) S.T.dy = 4 * Math.sin(ph(t, 1.55, 1.75) * Math.PI); },
  b: (g, t) => { const k = ph(t, .9, 1.35) * (1 - ph(t, 1.5, 1.6)); if (k > 0) { g.save(); g.globalAlpha = .5 * k; ell(g, FXc, GY - 1, 6 + 26 * k, 2 + 6 * k, '#000', 3); g.restore(); } },
  f: (g, t) => { const dn = ph(t, 1.35, 1.55); if (dn > 0 && dn < 1) { const x = lerp(FXc - 90, FXc - 14, dn), y = lerp(-20, FYc - 4, dn); for (let k = 0; k < 10; k++) line(g, x - k * 4, y - k * 6, x - k * 4 - 3, y - k * 6 - 6, k < 4 ? '#fff' : '#cfc4ff', 3 - Math.floor(k / 4)); for (let i = 0; i < 5; i++) spr(g, 'feather', x - 12 - i * 8, y - 12 - i * 10, 9, i, .8); } const e = ph(t, 1.5, 2.2); if (e > 0 && e < 1) { ring(g, FXc - 10, FYc, e, '#fff', '#a890f0', 48); star(g, FXc - 10, FYc, 26 * (1 - e) + 4, '#fff', 10, 0); for (let i = 0; i < 12; i++) spr(g, 'feather', FXc - 10 + Math.cos(i * .52) * 50 * e, FYc + Math.sin(i * 1.3) * 30 * e - 10 * e, 10, i + e * 5, 1 - e); } } });

// ===== PSYCHIC
add('psychic', 'move', 'Mind Crush', 'A translucent violet sphere forms around the foe, then shrinks: converging force lines, a pulsing grid and a ringing hum squeeze it, ending in an implosion flash and three outward shock rings.', 'new pixel sphere + gradient + rings', {
  tick: (t, S) => { const sq = ph(t, 1.0, 1.7); if (t > .6 && t < 1.8) { S.T.dx = Math.sin(t * 30) * 1.2 * sq; S.T.tint = ['#f85888', .15 + .25 * sq]; } hit(S, t, 1.65, 2.1, 1.7); },
  f: (g, t) => { const k = ph(t, .3, .7) * (1 - ph(t, 1.7, 1.85)), sq = ph(t, 1.0, 1.7); if (k > 0) { const r = lerp(46, 22, easeO(sq)); soft(g, FXc, FYc - 6, r + 10, '248,88,136', k * .9); ell(g, FXc, FYc - 6, r, r, '#ffd0e8', 2); ell(g, FXc, FYc - 6, r - 3, r - 3, '#f85888', 1); for (let i = 0; i < 10; i++) { const a = i * .63 + t * 2; line(g, FXc + Math.cos(a) * (r + 12), FYc - 6 + Math.sin(a) * (r + 12), FXc + Math.cos(a) * (r + 2), FYc - 6 + Math.sin(a) * (r + 2), '#fff', 1); } for (let i = -2; i <= 2; i++) { g.save(); g.globalAlpha = .4 * k; line(g, FXc - r + i * 2, FYc - 6 + i * r * .35, FXc + r - i * 2, FYc - 6 + i * r * .35, '#ffd0e8', 1); g.restore(); } } const e = ph(t, 1.7, 2.4); if (e > 0 && e < 1) { for (let i = 0; i < 3; i++) ring(g, FXc, FYc - 6, Math.max(0, e - i * .12), '#fff', '#f85888', 50); star(g, FXc, FYc - 6, 30 * (1 - e) + 4, '#fff', 12, 0); flash(g, t, 1.7, 1.85, '#ffd0e8', .4); } } });
add('psychic', 'move', 'Teleport Barrage', 'The user blinks out in a ring of pixels and reappears at four different spots around the foe (above, behind, front, below) - each arrival leaves a fading afterimage and lands one slash with a ring flash.', 'tinted attacker copies + new pixel blink rings + claw slashes', {
  tick: (t, S) => { S.A.a = t > .35 && t < 2.2 ? 0 : 1; hit(S, t, .95, 1.2, 1.4); hit(S, t, 1.25, 1.5, 1.4); hit(S, t, 1.55, 1.8, 1.4); hit(S, t, 1.85, 2.1, 1.8); },
  f: (g, t) => { const im = IM['A_' + FX.cur.type], w = im && im.naturalWidth ? (FX.imgW || Math.min(100, im.naturalWidth)) : 40, spots = [[-30, -40], [34, -6], [-34, 4], [4, -62]]; for (let i = 0; i < 4; i++) { const a = .9 + i * .3, u = ph(t, a, a + .2), fd = 1 - ph(t, a + .2, a + .5); if (u <= 0 || fd <= 0) continue; const x = FXc + spots[i][0], y = GY - 32 + spots[i][1]; g.save(); g.globalAlpha = fd * .8; tinted(g, 'A_' + FX.cur.type, x, y, w, '#ff6ac8', .45, spots[i][0] > 0 ? 0 : 1); g.restore(); ring(g, x, y, ph(t, a, a + .4), '#fff', '#f85888', 22); const e = ph(t, a + .05, a + .3); if (e > 0 && e < 1) { claw(g, x - spots[i][0] * .1, y - 14, FXc, FYc + 8, 6, e, '#6a2a58', '#fff', '#fff', 2.4, 1 - e * .4); spr(g, 'impact', FXc - 8, FYc - 6, 28 * (1 - e * .4), i, 1 - e); } } const b = ph(t, .3, .6); if (b > 0 && b < 1) for (let i = 0; i < 16; i++) px(g, AC.x + Math.cos(i * .39) * 20 * b, AC.y + Math.sin(i * .39) * 26 * b, 2, 2, '#ffd0e8'); } });

// ===== BUG
add('bug', 'move', 'Pin Missile Volley', 'Eight thin needle missiles pop out of the user, hang in a fan for a beat, then streak in curved lines to the foe one after another with bright tips; each needle sticks in with a tiny flash.', 'new pixel needles', {
  tick: (t, S) => { for (let i = 0; i < 8; i++) hit(S, t, 1.35 + i * .08, 1.42 + i * .08, 1.0); },
  f: (g, t) => { for (let i = 0; i < 8; i++) { const hover = ph(t, .3 + i * .04, .6), go = ph(t, 1.0 + i * .08, 1.4 + i * .08), a = -1.0 + i * .28, hx = AC.x + 26 + Math.cos(a) * 24, hy = AC.y + Math.sin(a) * 26, end = { x: FXc - 8 + (i % 3) * 5, y: FYc - 22 + i * 5 }; if (hover <= 0) continue; let x, y, ang; if (go <= 0) { x = hx; y = hy; ang = a; } else if (go < 1) { const p = arcP({ x: hx, y: hy }, end, 24 * (i % 2 ? 1 : -1), go), q = arcP({ x: hx, y: hy }, end, 24 * (i % 2 ? 1 : -1), Math.max(0, go - .04)); x = p.x; y = p.y; ang = Math.atan2(p.y - q.y, p.x - q.x); line(g, q.x - (p.x - q.x) * 3, q.y - (p.y - q.y) * 3, p.x, p.y, 'rgba(255,255,255,.5)', 1); } else { x = end.x; y = end.y; ang = .2; } const L = 9; line(g, x - Math.cos(ang) * L, y - Math.sin(ang) * L, x, y, '#e8f0ff', 1); line(g, x - Math.cos(ang) * L, y - Math.sin(ang) * L, x - Math.cos(ang) * L * .4, y - Math.sin(ang) * L * .4, '#a8b820', 1); px(g, x, y, 2, 2, '#fff'); if (go >= 1) { const e = ph(t, 1.4 + i * .08, 1.6 + i * .08); if (e > 0 && e < 1) star(g, x, y, 8 * (1 - e) + 2, '#fff6a0', 6, i); } } } });
add('bug', 'var', 'X-Scissor', 'Variation of a slash: two huge green blade-arms hack at the foe in an X - first a down-right cut, then a down-left one - and the glowing X scar stays on the foe with a burst of green shards.', 'new pixel crescents + shards', {
  tick: (t, S) => { S.A.dx = dashX(t, .4, .7, 2.0, 2.4); hit(S, t, .95, 1.2, 1.6); hit(S, t, 1.3, 1.55, 1.6); },
  f: (g, t) => { const a = ph(t, .9, 1.2), b = ph(t, 1.25, 1.55), fd = 1 - ph(t, 1.9, 2.3); g.save(); g.globalAlpha = fd; if (a > 0) crescent(g, FXc - 8, FYc - 6, 34, -2.4, -.6, 5, '#2a5a10', '#a8d820', '#fff', Math.min(1, a * 1.4)); if (b > 0) crescent(g, FXc - 8, FYc - 6, 34, -2.5 + 3.14, -.7 + 3.14 - 1.0, 5, '#2a5a10', '#a8d820', '#fff', Math.min(1, b * 1.4)); if (b >= 1) { line(g, FXc - 26, FYc - 30, FXc + 12, FYc + 22, '#e8ffb0', 2); line(g, FXc + 12, FYc - 30, FXc - 26, FYc + 22, '#e8ffb0', 2); } g.restore(); impactAt(g, t, 1.25, 1.55, FXc - 8, FYc - 6, '#fff', '#a8d820', 44); } });
add('bug', 'move', 'Sleep Spores', 'A soft golden-green cloud of spores drifts from the user in a gentle wave; sparkles dance inside it, and when it reaches the foe it sways, tints violet and little "Z"s float up as it falls asleep.', 'new gradient spore cloud + pixel sparkles', {
  tick: (t, S) => { if (t > 1.3 && t < 2.4) { S.T.dx = Math.sin(t * 5) * 2; S.T.tint = ['#8a68c8', .3]; S.T.rot = Math.sin(t * 3) * 2; } },
  f: (g, t) => { const k = 1 - ph(t, 2.1, 2.6); for (let i = 0; i < 12; i++) { const u = ph(t, .35 + hash(i) * .3, 1.4), x = lerp(76, FXc - 8, u) + Math.sin(i * 2 + t * 3) * 6, y = lerp(76, FYc - 8, u) + Math.cos(i * 3 + t * 2) * (4 + u * 12); if (u > 0) soft(g, x, y, 10 + u * 12, i % 2 ? '200,220,90' : '160,210,120', .75 * k); } for (let i = 0; i < 24; i++) { const u = ph(t, .4 + hash(i) * .3, 1.5); if (u > 0 && u < 1) px(g, lerp(80, FXc, u) + Math.sin(i * 3 + t * 6) * 10, lerp(76, FYc - 6, u) + Math.cos(i * 2 + t * 5) * 14, 2, 2, i % 2 ? '#fff6a0' : '#d8ff9a'); } if (t > 1.4 && t < 2.5) for (let i = 0; i < 3; i++) zz(g, FXc + 6 + i * 7, FYc - 44 - i * 8 - ((t * 10 + i * 4) % 6), 3 + i, '#e8e0ff'); } });

// ===== ROCK
add('rock', 'move', 'Rock Barrage', 'Boulders and rubble tear loose from the ground around the user and float up in a glowing ring (dust pouring off), then are flung one at a time at the foe with spinning trails and dust bursts on impact.', 'existing "rock" sprites + new pixel dust', {
  tick: (t, S) => { for (let i = 0; i < 6; i++) hit(S, t, 1.3 + i * .14, 1.4 + i * .14, 1.4); },
  f: (g, t) => { for (let i = 0; i < 6; i++) { const rise = ph(t, .3 + i * .06, .9), go = ph(t, 1.05 + i * .14, 1.4 + i * .14), a = t * 3 + i * 1.05, hx = AC.x + 18 + Math.cos(a) * 24, hy = lerp(GY - 6, 40 + Math.sin(a) * 10, easeO(rise)), end = { x: FXc - 8, y: FYc - 12 + (i % 3) * 10 }; if (rise <= 0) continue; if (go >= 1) { const e = ph(t, 1.4 + i * .14, 1.7 + i * .14); if (e > 0 && e < 1) { ring(g, end.x, end.y, e, '#e8d8a0', '#a89048', 22); for (let s = 0; s < 4; s++) puff(g, end.x + Math.cos(s * 1.6) * 16 * e, end.y + Math.sin(s * 1.6) * 12 * e, 4, '#c8b078', .5 * (1 - e)); } continue; } const x = lerp(hx, end.x, go), y = lerp(hy, end.y, go) - Math.sin(go * 3.14) * 12; if (go > 0) for (let k = 1; k < 4; k++) puff(g, lerp(hx, end.x, Math.max(0, go - k * .08)), lerp(hy, end.y, Math.max(0, go - k * .08)) - Math.sin(Math.max(0, go - k * .08) * 3.14) * 12, 5 - k, '#c8b078', .45); halo(g, x, y, 12, '#e0c068', rise * .5); spr(g, 'rock' + (1 + i % 3), x, y, 16 + (i % 3) * 3, t * 5 + i, 1); if (rise < 1) puff(g, hx, GY - 3, 5, '#c8b078', .4); } } });
add('rock', 'move', 'Rock Slide', 'A whole slope of boulders and gravel comes tumbling down the top-right corner toward the foe in a chaotic cascade, bouncing, spinning and kicking up dust clouds, burying the foe\'s feet in a rubble heap.', 'existing "rock" sprites + new pixel dust', {
  tick: (t, S) => { hit(S, t, 1.0, 2.2, 1.2); },
  f: (g, t) => { for (let i = 0; i < 16; i++) { const a = .3 + hash(i) * 1.3, u = ph(t, a, a + .75), ty = GY - 6 - hash(i + 3) * 4, tx = FXc - 40 + hash(i + 9) * 80; if (u <= 0) continue; const sx = tx + 90, sy = -20, bounce = u < 1 ? 0 : Math.abs(Math.sin((u - 1) * 9)) * 6 * (1 - ph(t, a + .75, a + 1.4)); const x = u < 1 ? lerp(sx, tx, u) : tx - ph(t, a + .75, a + 1.4) * 8, y = (u < 1 ? lerp(sy, ty, u * u) : ty) - bounce, fd = 1 - ph(t, 2.1, 2.6); if (u < 1) for (let k = 1; k < 4; k++) puff(g, lerp(sx, tx, Math.max(0, u - k * .04)), lerp(sy, ty, Math.pow(Math.max(0, u - k * .04), 2)), 5 - k, '#c8b078', .4); g.save(); g.globalAlpha = fd; spr(g, 'rock' + (1 + i % 3), x, y, 12 + (i % 4) * 5, t * 6 + i, 1); g.restore(); if (u >= 1 && u < 1.15) puff(g, tx, GY - 4, 7, '#c8b078', .5); } for (let i = 0; i < 5; i++) puff(g, FXc - 30 + i * 14, GY - 4 - ((t * 15 + i * 5) % 8), 7, '#d8c08a', .3 * env(t, 1.0, 1.4, 2.0, 2.5)); } });

// ===== GHOST
function skull(g, x, y, s, a) { g.save(); g.globalAlpha = a; disc(g, x, y, 5 * s, '#f2f0ff'); px(g, x - 3 * s, y + 3 * s, 6 * s, 4 * s, '#f2f0ff'); px(g, x - 3.2 * s, y - 1 * s, 2.4 * s, 2.6 * s, '#1a0a30'); px(g, x + .8 * s, y - 1 * s, 2.4 * s, 2.6 * s, '#1a0a30'); px(g, x - .5 * s, y + 2 * s, 1 * s, 1.4 * s, '#1a0a30'); for (let i = 0; i < 3; i++) px(g, x - 2 * s + i * 2 * s, y + 5 * s, 1 * s, 2 * s, '#1a0a30'); g.restore(); }
add('ghost', 'move', 'Wailing Skulls', 'Six wailing white skulls with glowing violet haloes fly out of the user in wobbling lines; sound-wave rings pulse from each, and as they pass through the foe it shudders in fear.', 'new pixel skulls + wave rings', {
  tick: (t, S) => { for (let i = 0; i < 6; i++) hit(S, t, 1.0 + i * .13, 1.12 + i * .13, 1.2); if (t > 1.0 && t < 2.2) S.T.tint = ['#9a6ad8', .25]; },
  f: (g, t) => { for (let i = 0; i < 6; i++) { const a = .4 + i * .13, u = ph(t, a, a + 1.0); if (u <= 0 || u >= 1) continue; const x = lerp(76, 250, u), y = 74 + (i - 2.5) * 9 + Math.sin(u * 12 + i) * 8, fd = 1 - ph(t, a + .8, a + 1.0); halo(g, x, y, 14, '#9a6ad8', fd * .8); for (let r = 0; r < 2; r++) { const w = (u * 4 + r * .5) % 1; g.save(); g.globalAlpha = (1 - w) * fd; ell(g, x + 8, y, 4 + 8 * w, 4 + 10 * w, '#d8c8ff', 1, -1.2, 1.2); g.restore(); } skull(g, x, y, 1.1, fd); } } });
add('ghost', 'move', 'Phase Strike', 'The user turns see-through and glides through the foe in a blue-violet streak (leaving a mirrored ghost trail), chills it as it passes, then reforms behind and glides back for a second pass.', 'tinted attacker copies + new pixel trail', {
  tick: (t, S) => { const a = ph(t, .5, 1.0), b = ph(t, 1.4, 1.9); S.A.dx = (TG.x + 50) * ease(a) - (TG.x + 50) * ease(b) ; S.A.a = (t > .45 && t < 2.0) ? .35 : 1; hit(S, t, .95, 1.2, 1.4); hit(S, t, 1.65, 1.9, 1.4); if (t > .95) S.T.tint = ['#9a6ad8', .2]; },
  f: (g, t, S) => { const ax = 46 + S.A.dx; if (t > .45 && t < 2.0) for (let k = 1; k < 6; k++) { const dir = ph(t, 1.4, 1.9) > 0 ? 1 : -1; g.save(); g.globalAlpha = .3 - k * .045; tinted(g, 'A_ghost', ax - dir * k * 10, GY - 30, (IM.A_ghost && IM.A_ghost.naturalWidth) ? Math.min(100, IM.A_ghost.naturalWidth) : 40, '#9a6ad8', .5, 1); g.restore(); } impactAt(g, t, 1.0, 1.25, FXc - 8, FYc - 6, '#e8e0ff', '#9a6ad8', 38); impactAt(g, t, 1.7, 1.95, FXc - 8, FYc - 6, '#e8e0ff', '#9a6ad8', 38); } });
